mapper.select:
SELECT status FROM quant_order
WHERE credential_id=#{credentialId} AND symbol=#{symbol} AND exchange_order_id=#{orderId}
LIMIT 1

mapper.sql:
WHERE record_type<>'FILL'
AND credential_id=#{q.credentialId}
AND strategy_name LIKE CONCAT('%',#{q.strategyName},'%')
AND strategy_instance_id=#{q.strategyInstanceId}
AND symbol=#{q.symbol}
AND run_mode=#{q.runMode}
AND operation=#{q.operation}
AND status=#{q.status}
AND reason LIKE CONCAT('%',#{q.reason},'%')
AND event_time>=#{from} AND event_time<=#{to}

mapper.select:
SELECT * FROM quant_trade_decision_log

ORDER BY event_time DESC,id DESC
LIMIT #{limit} OFFSET #{offset}
